def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    desperate_prev = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                    desperate_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    units = int(supply / WATER_REQ)
    if units < 0:
        units = 0

    if not alive:
        if hp <= 2 or no_water >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    desperate_anchor = max(desperate_prev) if desperate_prev else highest_prev

    critical_me = hp <= 2 or no_water >= 1
    very_safe = hp >= 7 and no_water == 0

    if units >= len(alive) + 1:
        base = DAILY_SALARY * 0.18
        if critical_me:
            base = DAILY_SALARY * 0.4
        return float(min(budget, max(0.0, base)))

    if units >= len(alive):
        base = max(DAILY_SALARY * 0.22, highest_prev * 0.45)
        if critical_me:
            base = max(base, DAILY_SALARY * 0.55)
        return float(min(budget, base))

    if units == 0:
        if critical_me:
            return float(min(budget, DAILY_SALARY * 0.98))
        return float(min(budget, DAILY_SALARY * 0.08))

    if units == 1:
        if critical_me:
            target = max(DAILY_SALARY * 1.1, desperate_anchor + 6.0, highest_prev + 3.0)
            return float(min(budget, target))
        if very_safe:
            return float(min(budget, DAILY_SALARY * 0.12))
        target = max(DAILY_SALARY * 0.42, highest_prev * 0.55)
        return float(min(budget, target))

    pressure = highest_prev
    if len(alive) >= 3:
        pressure = max(pressure, desperate_anchor)

    if critical_me:
        target = max(DAILY_SALARY * 0.92, pressure + 2.5)
        return float(min(budget, target))

    if very_safe and pressure >= DAILY_SALARY * 1.4:
        return float(min(budget, DAILY_SALARY * 0.18))

    target = max(DAILY_SALARY * 0.48, pressure * 0.72)
    if pressure <= DAILY_SALARY * 0.5:
        target = max(target, pressure + 1.5)
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    yesterday_pressures = []  # (bid, opp_hp_after)
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                b = float(bid)
            except Exception:
                continue
            yesterday_bids.append(b)
            hp_after = prev.get('hp_after', None)
            if hp_after is not None:
                try:
                    yesterday_pressures.append((b, int(hp_after)))
                except Exception:
                    pass

    # Fallback if traces missing
    if not yesterday_bids:
        if my_hp <= 2 or my_no_water_days >= 2:
            return float(min(my_budget, DAILY_SALARY * 0.9))
        return float(min(my_budget, DAILY_SALARY * 0.55))

    highest_prev_bid = max(yesterday_bids)
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

    # Estimate how many water units are available relative to requirement
    # Use int() indices: only for internal thresholds, not list access.
    units_available = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    # When supply is moderate (15-25) and WATER_REQ=9, units_available is typically 1.

    # Risk model: if my HP is low or I already have no-water days, bid more aggressively.
    critical = (my_hp <= 2) or (my_no_water_days >= 2)

    # If someone bid very high yesterday, they likely secured water; to avoid losing again, match/beat slightly.
    # Otherwise, bid around the median/high end but not full.
    sorted_bids = sorted(yesterday_bids)
    median_prev_bid = sorted_bids[len(sorted_bids)//2] if sorted_bids else highest_prev_bid

    # Determine target bid
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if critical:
            target = highest_prev_bid * 1.03
        else:
            # Slightly under/near the top to conserve budget
            target = max(median_prev_bid, second_prev_bid + 2.0)
            target = max(target, highest_prev_bid * 0.92)
    else:
        # No extreme pressure: bid to be competitive but not wasteful
        if critical:
            target = max(highest_prev_bid * 0.9, median_prev_bid + 10.0)
        else:
            # If units_available is low (likely 1), competition matters more
            if units_available <= 1:
                target = max(median_prev_bid + 5.0, second_prev_bid + 1.5)
            else:
                target = max(median_prev_bid, second_prev_bid + 0.5)

    # Convert target into a bounded bid with budget and salary constraints
    # Keep bids in a reasonable band to avoid overspending.
    upper_cap = DAILY_SALARY * 1.1
    lower_floor = DAILY_SALARY * 0.25
    bid = float(min(my_budget, min(upper_cap, max(lower_floor, target))))

    # If supply is at the low end, increase bid slightly since fewer units likely win.
    if supply <= float(MIN_SUPPLY) + 0.5:
        bid = float(min(my_budget, bid * 1.08))

    # Final safety clamp
    if bid < 0:
        bid = 0.0
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10 

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    bid_amount = DAILY_SALARY * 0.75 

    if my_hp <= 2:
        bid_amount = DAILY_SALARY * 1.05 
    elif my_hp == 3:
        bid_amount = DAILY_SALARY * 0.9
    elif my_hp >= 7:
        bid_amount = DAILY_SALARY * 0.65

    if my_no_water_days > 0:
        bid_amount = max(bid_amount, DAILY_SALARY * 1.1) 
        if my_no_water_days > 1:
            bid_amount = max(bid_amount, DAILY_SALARY * 1.25) 

    if current_supply <= MIN_SUPPLY + 3:
        bid_amount *= 1.1
    elif current_supply >= MAX_SUPPLY - 3:
        bid_amount *= 0.9

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.9:
            bid_amount = max(bid_amount, highest_prev_bid + 7)
        elif highest_prev_bid >= DAILY_SALARY * 0.75:
            bid_amount = max(bid_amount, highest_prev_bid + 3)
        else:
            bid_amount = max(bid_amount, highest_prev_bid + 1)

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2 and my_hp < 5:
        bid_amount = max(bid_amount, my_budget * 0.9)

    final_bid = min(my_budget, bid_amount)

    if final_bid < DAILY_SALARY * 0.1 and my_budget > 0 and remaining_days > 0:
        final_bid = min(my_budget, DAILY_SALARY * 0.1)

    return final_bid

